class Solution {public int[] solve(int n,int[][] edges){int m=edges.length;if(m==0)return new int[0];ArrayList<ArrayList<Integer>>a=new ArrayList<>();for(int i=0;i<n;i++)a.add(new ArrayList<>());int[] degree=new int[n],index=new int[n];for(int id=0;id<m;id++){a.get(edges[id][0]).add(id);degree[edges[id][0]]++;degree[edges[id][1]]--;}int start=edges[0][0],plus=0,minus=0;for(int v=0;v<n;v++)if(degree[v]==1){plus++;start=v;}else if(degree[v]==-1)minus++;else if(degree[v]!=0)return new int[]{-1};if(!((plus==0&&minus==0)||(plus==1&&minus==1)))return new int[]{-1};ArrayList<Integer>vertices=new ArrayList<>(),enter=new ArrayList<>(),out=new ArrayList<>();vertices.add(start);enter.add(-1);while(!vertices.isEmpty()){int u=vertices.get(vertices.size()-1);if(index[u]<a.get(u).size()){int id=a.get(u).get(index[u]++);vertices.add(edges[id][1]);enter.add(id);}else{vertices.remove(vertices.size()-1);int id=enter.remove(enter.size()-1);if(id>=0)out.add(id);}}if(out.size()!=m)return new int[]{-1};Collections.reverse(out);return out.stream().mapToInt(Integer::intValue).toArray();}}